package com.cpf.starter.realtime;import java.net.URI;import java.time.Duration;import java.util.function.Supplier;import org.springframework.http.*;import org.springframework.web.reactive.function.client.WebClient;import org.springframework.web.reactive.socket.*;import org.springframework.web.reactive.socket.client.WebSocketClient;import reactor.core.publisher.*;import reactor.util.retry.Retry;public final class CpfRealtimeClient {private final WebClient web;private final WebSocketClient ws;private final Supplier<String> token;private final int maxBuffered;public CpfRealtimeClient(WebClient w,WebSocketClient s,Supplier<String> t,int max){web=w;ws=s;token=t;maxBuffered=max;}public Flux<String> sse(URI uri){return web.get().uri(uri).header(HttpHeaders.AUTHORIZATION,"Bearer "+token.get()).accept(MediaType.TEXT_EVENT_STREAM).retrieve().bodyToFlux(String.class).onBackpressureBuffer(maxBuffered).retryWhen(Retry.backoff(Long.MAX_VALUE,Duration.ofMillis(200)).maxBackoff(Duration.ofSeconds(30)));}public Mono<Void> websocket(URI uri,Flux<String> outbound,java.util.function.Consumer<String> inbound){HttpHeaders h=new HttpHeaders();h.setBearerAuth(token.get());return ws.execute(uri,h,session->{Flux<WebSocketMessage> send=outbound.onBackpressureBuffer(maxBuffered).map(session::textMessage);Mono<Void> receive=session.receive().map(WebSocketMessage::getPayloadAsText).doOnNext(inbound).then();return session.send(send).and(receive);});}}
